INSERT INTO crm_wecom_kf_message (
    corp_id, open_kfid, external_userid, msgid, msgtype, content, direction, send_time,
    raw_json, conversation_id, media_id, pic_url, source, created_at
) VALUES (
    #{corpId}, #{openKfid}, #{externalUserid}, #{msgid}, #{msgtype}, #{content},
    #{direction}, #{sendTime}, #{rawJson}, #{conversationId}, #{mediaId}, #{picUrl},
    #{source}, #{createdAt}
)

mapper.select:
SELECT 
FROM crm_wecom_kf_message
WHERE corp_id = #{corpId} AND external_userid = #{externalUserid}

    AND open_kfid = #{openKfid}


    AND direction = #{direction}

ORDER BY send_time DESC

SELECT m.id, m.corp_id, m.open_kfid, m.external_userid, m.msgid, m.msgtype, m.content, m.direction, m.send_time, m.raw_json, m.conversation_id, m.media_id, m.pic_url, m.source, m.created_at FROM crm_wecom_kf_message m INNER JOIN crm_contact c ON c.wecom_external_userid = m.external_userid WHERE m.corp_id = #{corpId} AND c.contact_id = #{contactId}
AND m.open_kfid = #{openKfid}
ORDER BY m.send_time DESC

SELECT 
FROM crm_wecom_kf_message
WHERE corp_id = #{corpId}
  AND send_time >= #{startTime}
  AND send_time < #{endTime}

    AND open_kfid = #{openKfid}

ORDER BY send_time ASC
